export function announcementLayout(width,count){const n=Math.max(1,count),available=Math.max(0,width-20),gap=Math.min(8,available/(n*10)),cell=Math.max(0,(available-gap*(n-1))/n);return {gap,cell,mode:cell<68?'icons':cell<120?'compact':'full',icon:Math.max(2,Math.min(18,cell*.5))};}
let observer;
export function fitAnnouncements(box){const apply=()=>{if(!box.children.length)return;const {gap,cell,mode,icon}=announcementLayout(box.clientWidth||globalThis.innerWidth||320,box.children.length);box.dataset.mode=mode;box.style.setProperty('--ad-count',String(box.children.length));box.style.setProperty('--ad-gap',gap+'px');box.style.setProperty('--ad-icon-size',icon+'px');box.style.setProperty('--ad-font-size',Math.max(10,Math.min(14,cell/9))+'px');};apply();if(typeof ResizeObserver!=='undefined'){observer?.disconnect();observer=new ResizeObserver(apply);observer.observe(box);}else{globalThis.addEventListener?.('resize',apply,{once:true});}}
